export function calculate(rule,input={},coupon=null){const base=Math.round(expression(rule.formula,answers(rule,input))*100);if(base<0)throw Error('Estimate cannot be negative.');const automatic=rule.discount.type==='percent'?Math.round(base*rule.discount.value/100):Math.round(rule.discount.value*100);let promotional=0;if(coupon){if(!coupon.active||(coupon.expires&&coupon.expires<new Date().toISOString().slice(0,10))||base<Math.round(coupon.minimum*100)||(coupon.rules?.length&&!coupon.rules.includes(rule.id)))throw Error('This discount code is not eligible.');promotional=coupon.type==='percent'?Math.round(base*coupon.value/100):Math.round(coupon.value*100);}const discount=Math.min(base,Math.max(automatic,promotional)),net=base-discount,tax=Math.round(net*rule.taxPercent/100),total=net+tax;const deposit=Math.min(total,rule.deposit.type==='percent'?Math.round(total*rule.deposit.value/100):Math.round(rule.deposit.value*100));return {subtotal:base,discount,net,tax,total,deposit,balance:total-deposit,currency:'CAD',ruleId:rule.id,revision:rule.revision||0,coupon:promotional>automatic?coupon.code:''};}
// Design surfaces ("sides") per product. Vehicles and apparel sleeves have their own artboard size.
export function sideViews(product){if(product.views)return product.views;if(product.group==='Apparel'){const g=product.garment?.group;if(g==='hats')return [{key:'front',label:'Front'}];if(g==='totes')return [{key:'front',label:'Front'},{key:'back',label:'Back'}];return [{key:'front',label:'Front'},{key:'back',label:'Back'},{key:'left-sleeve',label:'Left sleeve',width:3.5,height:3.5},{key:'right-sleeve',label:'Right sleeve',width:3.5,height:3.5}];}return product.twoSided?[{key:'front-outside',label:product.folds.length?'Outside':'Front'},{key:'back-inside',label:product.folds.length?'Inside':'Back'}]:[{key:'front-outside',label:'Front'}];}
export const sideSlots=product=>product.views?product.views.length:product.group==='Apparel'?4:2;
// Quick artwork shapes, drawn in a 100 × 100 box.
export const SHAPES={star:'M50 3 61.8 35.6 96.6 36.2 69 57.4 79.4 90.6 50 70.8 20.6 90.6 31 57.4 3.4 36.2 38.2 35.6Z',heart:'M50 92C22 70 4 53 4 31 4 15 16 5 29 5c9 0 16 5 21 13C55 10 62 5 71 5c13 0 25 10 25 26 0 22-18 39-46 61Z',triangle:'M50 4 97 94H3Z',arrow:'M3 36h56V10l38 40-38 40V64H3Z',badge:'M50 2 62 12 78 9 83 24 97 32 91 47 97 62 83 70 78 85 62 82 50 92 38 82 22 85 17 70 3 62 9 47 3 32 17 24 22 9 38 12Z',hexagon:'M25 5h50l24 45-24 45H25L1 50Z',check:'M8 52 22 38 40 56 78 14 93 28 40 86Z',speech:'M10 6h80a8 8 0 0 1 8 8v48a8 8 0 0 1-8 8H42L20 94V70H10a8 8 0 0 1-8-8V14a8 8 0 0 1 8-8Z'};
